-- CreateTable
CREATE TABLE "space_objects" (
    "spaceId" TEXT NOT NULL,
    "objectId" TEXT NOT NULL,
    "value" TEXT NOT NULL,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "space_objects_pkey" PRIMARY KEY ("spaceId","objectId")
);

-- AddForeignKey
ALTER TABLE "space_objects" ADD CONSTRAINT "space_objects_spaceId_fkey" FOREIGN KEY ("spaceId") REFERENCES "spaces"("id") ON DELETE CASCADE ON UPDATE CASCADE;

